// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _caller) public {
        // First, set the approved status to a random value
        bool expected = true;
        if (_caller != address(0)) {
            vm.prank(address(1)); // some non-owner address
            (bool success, ) = address(c).call(abi.encodeWithSelector(c.setApprovedLogger.selector, _caller, true));
            // If caller is not owner, the call fails; in that case we still check the mapping via getter
        }
        // Use the owner to set the logger status deterministically
        vm.prank(address(this)); // assume this contract is not the owner; we need the actual owner
        // Actually, owner is set to address(0) by default because _contractOwner is private and uninitialized?
        // Let's just assume owner can be address(this) via a prank
        // Simpler: test the property that approvedToLog returns true for all addresses in the mutant, but not in the reference
        // Since we can't change the mapping easily without owner prank, we test the equivalence:
        // reference: approvedToLog(x) == approvedLoggers[x]
        // mutant: approvedToLog(x) == true, which breaks when approvedLoggers[x] is false
        bool referenceValue = c.approvedToLog(_caller);
        bool mappingValue = c.approvedLoggers(_caller);
        assertTrue(referenceValue == mappingValue, "approvedToLog must equal mapping value");
    }
}

